/// Brand identity data used for paper entry tiles. SVG paths are from Simple
/// Icons (CC0) and remain local — no network image loading is required.
class Brand {
  final String name;
  final String path;
  final Color color;
  final String domain;
  const Brand(this.name, this.path, this.color, this.domain);

  String get svg =>
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="#FFFFFF" d="$path"/></svg>';
}

